(function() {
  // Avoid running multiple times on same element
  if (element.querySelector('.pin-info-overlay')) return;

  // Get the description from aria-label of the first link or img alt
  var description = '';
  var pinLink = element.querySelector('a[aria-label]');
  if (pinLink) {
    description = pinLink.getAttribute('aria-label') || '';
  }
  if (!description) {
    var img = element.querySelector('img[alt]');
    if (img) {
      description = img.getAttribute('alt') || '';
    }
  }
  if (!description) return;

  // Get the domain/source from attribution if available
  var domain = '';
  var attributionEl = element.querySelector('[data-test-id="related-pins-name"] div[title]');
  if (attributionEl) {
    domain = attributionEl.getAttribute('title') || attributionEl.textContent || '';
  }

  // Find the image wrapper to insert after
  var imageWrapper = element.querySelector('.PinCard__imageWrapper');
  if (!imageWrapper) return;

  // Create the info container
  var infoContainer = document.createElement('div');
  infoContainer.className = 'pin-info-overlay';
  infoContainer.style.cssText = 'padding: 6px 8px; background-color: #f0f0f0; border-radius: 0 0 12px 12px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;';

  // Description line
  var descDiv = document.createElement('div');
  descDiv.style.cssText = 'font-size: 12px; color: #333; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 2px;';
  descDiv.textContent = description;
  infoContainer.appendChild(descDiv);

  // Domain line (if available)
  if (domain) {
    var domainDiv = document.createElement('div');
    domainDiv.style.cssText = 'font-size: 11px; color: #888; font-weight: 500;';
    domainDiv.textContent = domain;
    infoContainer.appendChild(domainDiv);
  }

  // Insert after the image wrapper
  imageWrapper.parentNode.insertBefore(infoContainer, imageWrapper.nextSibling);
})();
